  "codebook": {
    "definition": "Credit-claiming is defined as any announcement or statement in which a senator claims personal or joint responsibility for securing a specific, positive government outcome, benefit, project, allocation of federal funds, or legislative passage that is desirable to their constituents or the general public.",
    "clarification": "To classify a document as '1' (credit-claiming), the text must explicitly note that the senator (or their direct delegation/subcommittee) successfully acted to bring about a completed or finalized outcome. This includes securing federal grants for local projects, passing a sponsored bill or amendment, successfully enacting a policy through personal intervention, or directly lobbying/working with executive agencies to yield a concrete benefit. The key is the association of the senator's effort with a successful or finalized positive outcome.",
    "positive_examples": [
      {
        "document_id": "1862",
        "explanation": "This press release features explicit credit-claiming because Senators Baucus and Tester claim direct responsibility for 'delivering on their promise to secure' and going 'to bat' for $12.5 million in federal funding for vital military projects in Butte, Montana."
      },
      {
        "document_id": "2627",
        "explanation": "Senator Talent claims joint/personal credit by announcing that the Senate has approved his specific request for $1.5 million in federal funding for a state university's health facility."
      }
    ],
    "negative_clarification": "A text should be classified as '0' (not credit-claiming) if it represents only general position-taking, criticism of opponents/the administration, or expressions of support for pending legislation that has not yet passed. Introducing a bill, calling on an agency to act without achieving a finalized outcome, announcing an upcoming event (such as a town hall), or issuing symbolic statements (e.g., eulogies, holiday commemorations) do not count as credit-claiming under this definition.",
    "negative_examples": [
      {
        "document_id": "656",
        "explanation": "This release is a highly critical statement focusing on the administration's port security policy. Senator Kerry takes a strong position and criticizes the government but does not claim credit for any positive, achieved government outcome."
      },
      {
        "document_id": "4531",
        "explanation": "Although the senators are actively initiating a policy, this document only announces the introduction of a new bill. Because there is no completed policy outcome or funding secured yet, this represents position-taking and legislative initiative, not credit-claiming."
      }
    ]
  }
}
